import{_ as r,o as a,c as t,a5 as s}from"./chunks/framework.CXroN2RO.js";const i="/study/images/browser/streams-flow.svg",o="/study/images/browser/streams-lifecycle.svg",g=JSON.parse('{"title":"Streams APIとストリーミング処理 — データの流れとbackpressure","description":"","frontmatter":{"title":"Streams APIとストリーミング処理 — データの流れとbackpressure","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"ReadableStream、WritableStream、TransformStreamの役割とchunk・待ち行列を説明する。highWaterMarkとdesiredSize、writeとreadyのPromise、pipeToの伝播、終了・取消し・lock、UTF-8の分割境界を整理する。","aliases":["Streams API","streaming","ストリーミング","ReadableStream","WritableStream","TransformStream","chunk","underlying source","underlying sink","pull","push","backpressure","desiredSize","highWaterMark","writer.ready","pipeTo","pipeThrough","cancel","abort","close","releaseLock","TextDecoderStream"],"verification":"一次資料照合（2026-11-05）"}},"headers":[],"relativePath":"browser/streams-backpressure.md","filePath":"browser/streams-backpressure.md"}'),n={name:"browser/streams-backpressure.md"};function l(d,e,c,p,h,k){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="streams-apiとストリーミング処理-—-データの流れとbackpressure" tabindex="-1">Streams APIとストリーミング処理 — データの流れとbackpressure <a class="header-anchor" href="#streams-apiとストリーミング処理-—-データの流れとbackpressure" aria-label="Permalink to &quot;Streams APIとストリーミング処理 — データの流れとbackpressure&quot;">​</a></h1><p><strong>ストリーミング処理</strong>は、届いた部分から順に受け取り、変換し、次の処理へ渡す方式です。ブラウザの<strong>Streams API</strong>は、その流れ、待ち行列、終了や失敗を扱う標準APIです。</p><p><a href="/study/browser/worker-pool-backpressure.html">Worker poolの受付制御</a>と同様に、作る側が速いとデータがたまります。ただし、Streamの閾値は「待機4件を超えたら拒否」という固定上限とは異なります。<strong>供給を抑える合図、処理完了、資源の解放を分けて読みます。</strong></p><h2 id="readable、writable、transformとchunk" tabindex="-1">readable、writable、transformとchunk <a class="header-anchor" href="#readable、writable、transformとchunk" aria-label="Permalink to &quot;readable、writable、transformとchunk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>種類</th><th>役割</th></tr></thead><tbody><tr><td><code>ReadableStream</code></td><td>データを読み出す側へ提供する。下に実際の生成元であるsourceがある</td></tr><tr><td><code>WritableStream</code></td><td>データを書き込む入口を提供する。下に実際の処理先であるsinkがある</td></tr><tr><td><code>TransformStream</code></td><td>writable側で入力を受け、変換結果をreadable側へ出す</td></tr></tbody></table><p><strong>chunk</strong>は、一回に渡すデータ片です。バイト列、文字列、オブジェクトなど、Streamの契約に合う値を扱い、一定byte数・文字数とは限りません。変換では一入力に対する出力が0個や複数個の場合もあります。<a href="https://streams.spec.whatwg.org/#model" target="_blank" rel="noreferrer">WHATWG Streams: Model</a></p><p><strong>reader</strong>と<strong>writer</strong>は読み書きの窓口です。<strong>controller</strong>はsourceや変換処理などからデータ・終了・失敗を知らせます。<code>controller.enqueue(chunk)</code>で供給した未消費データは、内部queueへ入る場合があります。</p><p>Streamをつなぐだけで、計算を別のOSスレッドへ移すことにはなりません。自分で書いた<code>pull</code>、<code>transform</code>、<code>write</code>などの計算にも実行時間が必要です。<a href="/study/browser/web-workers-messages.html">Worker</a>への分担は別の仕組みです。</p><h2 id="pullとpushでは、作る側の抑え方が異なる" tabindex="-1">pullとpushでは、作る側の抑え方が異なる <a class="header-anchor" href="#pullとpushでは、作る側の抑え方が異なる" aria-label="Permalink to &quot;pullとpushでは、作る側の抑え方が異なる&quot;">​</a></h2><p><strong>pull型</strong>は需要に応じて次を生成・取得する方式で、独自ReadableStreamの<code>pull(controller)</code>が供給を求められる入口です。queueの空きや保留中のreadなどが関係し、<code>read()</code>一回と必ず対応するわけではありません。read前にqueueを満たすために呼ばれ得ます。<a href="https://streams.spec.whatwg.org/#underlying-source-api" target="_blank" rel="noreferrer">WHATWG Streams: Underlying source API</a></p><p><strong>push型</strong>は外側の機器やイベント源などから供給される方式で、その停止・再開へ抑制をつなぎます。<code>enqueue</code>だけで外側の生成は自動停止しません。止められない入力なら、容量や取りこぼし、失敗条件も決めます。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Streams_API/Concepts" target="_blank" rel="noreferrer">MDN: Streamsのsourceとbackpressure</a></p><h2 id="desiredsizeとhighwatermarkは、抑制のための情報" tabindex="-1">desiredSizeとhighWaterMarkは、抑制のための情報 <a class="header-anchor" href="#desiredsizeとhighwatermarkは、抑制のための情報" aria-label="Permalink to &quot;desiredSizeとhighWaterMarkは、抑制のための情報&quot;">​</a></h2><p><strong>highWaterMark</strong>は、queueの大きさに対してbackpressureを判断する閾値です。<strong>desiredSize</strong>は、通常の動作中には、概念的に次の差で表します。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>desiredSize = highWaterMark − queue内で数えているサイズの合計</span></span></code></pre></div><p><code>CountQueuingStrategy</code>は一chunkを1、<code>ByteLengthQueuingStrategy</code>はchunkの<code>byteLength</code>で数えます。件数とbyte数では閾値の意味が違います。また、終了・失敗などの状態によりdesiredSizeがnullなどになる場合もあり、常に単純な空き容量の数値ではありません。<a href="https://streams.spec.whatwg.org/#queuing-strategies" target="_blank" rel="noreferrer">WHATWG Streams: Queuing strategies</a></p><p>件数単位でhighWaterMarkが2なら、queueサイズ1では差は1、サイズ3では−1です。供給を抑える情報であり、必ず三つ目を拒否してメモリを確保しない、という契約ではありません。</p><p><strong>highWaterMarkはメモリの厳密な上限ではありません。</strong> 巨大なchunk、合図を無視するsource、大量の変換出力、別の配列への結果保存などでも保持量は増えます。複数段には各queueや処理中のデータもあります。chunkの最大サイズ、段ごとの保持、外側の生成元まで含めて設計します。<a href="https://streams.spec.whatwg.org/#internal-queues" target="_blank" rel="noreferrer">WHATWG Streams: Internal queues</a></p><figure><img src="'+i+'" alt="sourceからReadableStream、pipeTo、WritableStream、sinkへ流れるchunkと、消費側から上流へ戻るbackpressure、段ごとのqueueを示す図" width="760" height="1510" loading="lazy"><figcaption>chunkは下流へ、供給を抑える合図は上流へ伝わります。各queueの閾値だけで、処理全体のメモリ使用量が固定されるわけではありません。<a href="/study/images/browser/streams-flow.svg" target="_blank" rel="noopener">図を拡大する</a></figcaption></figure><h2 id="writeのpromiseと、writer-readyを混同しない" tabindex="-1">writeのPromiseと、writer.readyを混同しない <a class="header-anchor" href="#writeのpromiseと、writer-readyを混同しない" aria-label="Permalink to &quot;writeのPromiseと、writer.readyを混同しない&quot;">​</a></h2><table tabindex="0"><thead><tr><th>API</th><th>待つ意味</th></tr></thead><tbody><tr><td><code>writer.write(chunk)</code>が返すPromise</td><td>その書き込み操作の成功または失敗</td></tr><tr><td><code>writer.ready</code></td><td>writable側のbackpressureがかかっていない状態への合図</td></tr><tr><td><code>writer.close()</code>が返すPromise</td><td>先行する書き込みを進め、sinkを正常に閉じる処理の完了</td></tr></tbody></table><p><code>ready</code>は特定chunkの書き込み完了通知ではありません。閾値に余裕があれば、書き込み未完了でもfulfilledの場合があります。正常なwritableでdesiredSizeが非正から正へ戻ることが、backpressureの解除に関係します。<a href="https://streams.spec.whatwg.org/" target="_blank" rel="noreferrer">WHATWG Streams: Writerによるflow control</a></p><p><code>write</code>の成功の意味はsinkの契約次第で、永続保存やネットワーク相手の処理完了まで示すとは限りません。独自sinkの<code>write</code>で非同期処理をするなら、その完了を表すPromiseを返します。timerだけ開始して戻れば、Streamには先に書き込み完了と扱われ得ます。大量のwriteやPromiseを別にためる保持量にも注意します。<a href="https://developer.mozilla.org/en-US/docs/Web/API/WritableStreamDefaultWriter/write" target="_blank" rel="noreferrer">MDN: writer.write</a>、<a href="https://developer.mozilla.org/en-US/docs/Web/API/WritableStreamDefaultWriter/ready" target="_blank" rel="noreferrer">MDN: writer.ready</a></p><h2 id="pipetoで流れと伝播をつなぐ" tabindex="-1">pipeToで流れと伝播をつなぐ <a class="header-anchor" href="#pipetoで流れと伝播をつなぐ" aria-label="Permalink to &quot;pipeToで流れと伝播をつなぐ&quot;">​</a></h2><p><code>readable.pipeTo(writable)</code>は、chunkを渡し、書き込み先の状況に応じて読み進めます。<code>pipeThrough(transform)</code>は変換のwritable側へ流し、そのreadable側を返します。接続に沿ってbackpressureを扱うための仕組みです。</p><p><code>pipeTo</code>が返すPromiseは、pipe処理が正常に終わればfulfilled、失敗すればrejectedになります。基本となる、伝播を抑止しない設定では次の関係があります。</p><table tabindex="0"><thead><tr><th>起きたこと</th><th>接続先への伝播</th></tr></thead><tbody><tr><td>sourceが正常に閉じる</td><td>destinationを正常にcloseする</td></tr><tr><td>sourceがerrorになる</td><td>destinationをabortする</td></tr><tr><td>destinationがerrorになる</td><td>sourceをcancelする</td></tr><tr><td>pipeへ渡したAbortSignalがabortされる</td><td>sourceをcancelし、destinationをabortする</td></tr></tbody></table><p>これは基本の伝播方向であり、終了済みの状態や競合により、sourceのcancelとsinkのabortのコールバックが両方必ず呼ばれる保証ではありません。相対順も固定しません。<code>preventClose</code>、<code>preventAbort</code>、<code>preventCancel</code>で伝播を抑止するなら、残した側を誰が扱うかも決めます。<a href="https://streams.spec.whatwg.org/#rs-pipe-to" target="_blank" rel="noreferrer">WHATWG Streams: pipeTo</a>、<a href="https://developer.mozilla.org/en-US/docs/Web/API/ReadableStream/pipeTo#parameters" target="_blank" rel="noreferrer">MDN: pipeToのoptions</a></p><h2 id="close、cancel、abort、errorは同じ終了ではない" tabindex="-1">close、cancel、abort、errorは同じ終了ではない <a class="header-anchor" href="#close、cancel、abort、errorは同じ終了ではない" aria-label="Permalink to &quot;close、cancel、abort、errorは同じ終了ではない&quot;">​</a></h2><p>readableの<strong>close</strong>は、供給側が正常な終わりを示す操作です。すでにqueueにあるchunkは読み出せ、その後のreadが<code>done: true</code>になります。writableのcloseは、新しい書き込みを終え、先行する書き込みとsinkの正常終了を進める操作です。</p><p>readableの<strong>cancel</strong>は、読み手が「残りはもう要らない」と知らせる操作で、queue内の未読データを破棄し、sourceの取消し手続きへつながります。writableの<strong>abort</strong>は、正常な完走をやめる操作です。<strong>error</strong>は、読み書きが失敗した状態を表します。error化と、独自sourceやsinkのcancel／abortコールバックが呼ばれることも、同じものとしては扱いません。</p><p>取消しやabortは、すでに起きた副作用を巻き戻しません。実行中のsinkの書き込みを、任意の瞬間で強制停止する保証もありません。<code>AbortController.abort()</code>を呼んだことと、<code>pipeTo</code>のPromiseが決着し、独自の片付けが終わったことを分けて管理します。これは前章の「結果が不要でも、実処理の枠は残る」という観点につながります。<a href="https://streams.spec.whatwg.org/#rs-model" target="_blank" rel="noreferrer">WHATWG Streams: Readable / Writable streams</a>、<a href="https://streams.spec.whatwg.org/#readable-stream-pipe-to" target="_blank" rel="noreferrer">Pipe処理の終了規則</a></p><figure><img src="'+o+`" alt="正常終了close、読取側のcancel、書込側のabort、errorとpipeToでの伝播、pipe終了時のlock解放を区別する図" width="760" height="1510" loading="lazy"><figcaption>close、cancel、abort、errorは意味と伝播先が異なります。<code>releaseLock</code>も、取消しや正常終了の代わりにはなりません。<a href="/study/images/browser/streams-lifecycle.svg" target="_blank" rel="noopener">図を拡大する</a></figcaption></figure><h2 id="lockとreleaseは、資源の停止とは別" tabindex="-1">lockとreleaseは、資源の停止とは別 <a class="header-anchor" href="#lockとreleaseは、資源の停止とは別" aria-label="Permalink to &quot;lockとreleaseは、資源の停止とは別&quot;">​</a></h2><p><code>getReader()</code>や<code>getWriter()</code>で窓口を得ると、Streamは<strong>lock</strong>されます。読み手や書き手の利用を排他的に管理する仕組みで、OSのmutex取得や別スレッドの生成ではありません。pipeToも処理中は両側をlockします。</p><p><code>releaseLock()</code>はその窓口の利用権を解放し、巻き戻し・cancel・closeはしません。保留中のreadを残してreaderのlockを解放すると、そのPromiseはTypeErrorでrejectedになります。未読chunkは別のreaderで読める場合があります。処理の決着と、lock解放の順序も設計します。<a href="https://developer.mozilla.org/en-US/docs/Web/API/ReadableStreamDefaultReader/releaseLock" target="_blank" rel="noreferrer">MDN: reader.releaseLock</a></p><h2 id="chunk境界は、通信や文字の境界とは限らない" tabindex="-1">chunk境界は、通信や文字の境界とは限らない <a class="header-anchor" href="#chunk境界は、通信や文字の境界とは限らない" aria-label="Permalink to &quot;chunk境界は、通信や文字の境界とは限らない&quot;">​</a></h2><p>Fetchの<code>Response.body</code>は本文のStreamを公開し、本文がなければnullです。chunkの区切りは、TCPパケット、HTTPの一要求、送信側のwrite一回、文字一個の境界とは別です。<a href="https://fetch.spec.whatwg.org/#body-mixin" target="_blank" rel="noreferrer">WHATWG Fetch: Bodies / Body mixin</a></p><p>例えばUTF-8の「あ」は<code>E3 81 82</code>という3byteですが、<code>E3</code>と<code>81 82</code>の別chunkになる場合があります。chunkごとに新しいTextDecoderで完結した入力として解釈すると、途中までしかない文字を不正列として扱う原因になります。<a href="/study/data/unicode-and-encoding.html">Unicodeと文字コード</a>の、byteと文字の区別がここでも必要です。</p><p><strong>TextDecoderStream</strong>は、分割入力の状態を保ってバイト列を文字列へ変換します。次は準備済みのbyteSourceと、文字列を受け取るtextSinkの接続例です。呼び出し元で、この関数のPromiseの成功・失敗を受け取ります。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> decodeToTextSink</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">byteSource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">textSink</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> textSource</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> byteSource.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pipeThrough</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TextDecoderStream</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;utf-8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { fatal: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  );</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> textSource.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pipeTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(textSink);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>fatal: true</code>では、不正なUTF-8をTypeErrorとして扱い、変換の失敗につなげます。復元した文字列も、改行やJSON一件ずつの区切りとは限りません。必要な区切りの保持・解析は別です。<a href="https://encoding.spec.whatwg.org/#interface-textdecoderstream" target="_blank" rel="noreferrer">WHATWG Encoding: TextDecoderStream</a></p><h2 id="実践と、観測の範囲" tabindex="-1">実践と、観測の範囲 <a class="header-anchor" href="#実践と、観測の範囲" aria-label="Permalink to &quot;実践と、観測の範囲&quot;">​</a></h2><p><a href="/study/practice/browser/stream-backpressure-observation.html">Streamのbackpressureを観察する実践</a>では、pullで4byteのUint8Arrayを8個生成します。件数単位のhighWaterMarkはreadableが2、writableが1で、sinkのwriteは600msのtimer待機を返します。これは消費の遅さを見せる教材で、CPU計算やネットワークの性能測定ではありません。</p><p>中断時は、pipeToと独自writeの待機が同じAbortSignalを監視します。待機側でtimerを解除し、中断したwriteのPromiseを同じreasonでrejectします。通常消費の完了には数えません。中断要求後も、pipeが既に読み出したchunkのwriteを始める場合があるため、write開始時にもsignalの中断状態を確認します。sinkのabortコールバックだけでtimerを解除しようとすると、pipe側が進行中writeの決着を待つため、互いに待ち続ける設計になり得ます。実践はpipeToの終端とlock解放を確認してから再実行します。</p><p>sourceの正常終了からpipeの終了処理が進み始めた後は、pipeへ送る中断要求だけで、その終了経路を変更できるとは限りません。この例は進行中write自身もsignalを監視して失敗を返すため、最後のwriteの中断を成功に取り違えません。すでに閉じたsourceやerrorになったsinkでは、cancel／abortのコールバックが呼ばれない場合もあります。</p><p>生成数generated、書き込み開始数started、消費完了数completedを表示します。<code>generated − completed</code>は内部queueの長さではなく、処理中や、中断後は未消費の累計差も含みます。ログから、全バッファ、物理メモリ上限、ネットワーク受信量、描画完了を測ったことにはしません。</p>`,46)])])}const b=r(n,[["render",l]]);export{g as __pageData,b as default};
